-- Megaverse in Flames: Soulmancy spells, levels one to five.
-- 18 spells rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~340-megaverse-in-flames-spells-a.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
-- Soulmancy, levels one to five, by the spell list on printed p.91; every level
-- agrees with the description headings (p.92-96) and the Contents (p.4). Every
-- cost and stat line was read off a render. Soulmancy: Death Trance is NOT linked
-- to the held RUE Death Trance by same_spell_as: this book gives three minutes per
-- level where RUE gives 10 melee rounds, so same-spell-lib's comparison fails on
-- duration; the RUE figure is in its variant_note.

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
  ('Soulmancy: Blood Ink', 1, 1, '1 P.P.E. plus one S.D.C. from a cut to the fingertip', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.92', 'rifts', 'Touch only', 'Three minutes per level of the caster', NULL, 'Not applicable', NULL, NULL, 'The caster nicks a fingertip and, for the duration, writes with his own blood as though the finger were a quill. It grants no literacy; it only lets him letter, draw or mark symbols on any solid surface. The blood sets in about fifteen seconds and is as stubborn to scrub off as any dried bloodstain. Blood Warriors and Soulmancers favour it for grisly warnings daubed on walls and vehicles, but it serves just as well for blazing a trail or ordinary notes; guiding the blood along a fingernail gives a fine line instead of the usual finger-wide scrawl.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Death Trance', 1, 1, NULL, 'Rifts Ultimate Edition p.198 (held as Death Trance) gives the duration as 10 melee rounds (two and a half minutes) per level of experience; this book prints three minutes per level, so the two rows are not linked by same_spell_as.', 'import', 'Rifts World Book 35: Megaverse in Flames p.92', 'rifts', 'Self only', 'Three minutes per level of the spell caster', NULL, 'None', NULL, NULL, 'The caster drops into a trance that passes for death: no breath, no pulse, no heartbeat, nothing to show he lives. He is helpless while it lasts, able neither to move, talk nor work magic, and senses only vague impressions such as being handled, moved or hearing speech, without recognising who or remembering details. He may end the trance whenever he wishes.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Peer into the Soul', 1, 8, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.92', 'rifts', '100 feet (30.5 m)', 'One melee', NULL, 'None', NULL, NULL, 'Much like See Aura, but aimed at the life essence. The caster learns: whether the subject has a soul at all or is a hollow automaton whose soul was taken; whether the soul is that of a mortal or of something else (supernatural being, creature of magic, deity or avatar, undead, entity or unknown), without learning which; whether the soul leans good, selfish or evil, though not the exact alignment; whether the subject is possessed or bound to a demon, Deevil, god or similar power, which exposes vampires, avatars, priests, witches, Soulmancers, Blood Warriors and the like; and the body''s health plus a rough experience band (1-3 low, 4-7 medium, 8-15 high, above 15 incredibly high).', NULL, 'soulmancy', NULL),
  ('Soulmancy: Acid Blood Spit', 2, 5, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.92', 'rifts', '3 feet (0.9 m) per level of the spell caster', 'Instant, plus the acid burns for 1D4 additional melees', '1D6 M.D. on impact, then 1 M.D. per melee round for one melee round per level of the spell caster; equivalent S.D.C. damage to S.D.C. organic matter', '-2 to dodge', NULL, NULL, 'The caster spits a glob of demon-like acidic blood that burns whatever it hits; dodging is the only defence, and most targets never see it coming. Aiming for an eye takes a Called Shot at -5, and the defender may parry without penalty, though whatever blocks the glob is burned instead. An eye that is hit is destroyed outright (the acid then stops): Bio-Regenerating beings regrow it in 2D6+12 hours, mortals stay blind in that eye unless magic, bionics or a Bio-System replace it, and the splash costs 1D4 P.B. Against S.D.C. flesh, plants and other organic matter it does the same numbers as S.D.C. damage.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Bath (Super-Healing)', 2, 13, '13 P.P.E., plus 9 for each additional person healed in the same bath', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.92-93', 'rifts', 'Touch; immersion', 'One minute of healing time; results are instant', NULL, 'Standard, but can be rolled every melee', NULL, 'Cast once the patient is immersed; filling the tub from scratch takes at least ten human-sized victims and 2D6+20 minutes', 'A tub, pool or other vessel big enough to submerge a person from chin to toe is filled with the blood of slain humanoids, enemies or innocents alike. With the patient inside, the spell warms the blood and one full minute of soaking heals 5D6+6 M.D.C., or for an S.D.C. being 2D4x10 Hit Points plus 1D6x10 S.D.C.; it also sets broken bones to knit in about a third of the normal time, and mends internal bleeding, organ and heart damage and poisoning. Chronic blood and autoimmune illness is not cured but held in check for 30 days. One pool can be re-enchanted as many times as the caster has levels, but spoils after 24 hours. Alternatively the bath undoes the first one or two bites of a vampire''s Slow Kill and frees a victim from vampiric enslavement, though the same vampire can re-enslave with one bite at -9 to save; it cannot turn a vampire mortal again.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Splatter', 2, 8, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.93', 'rifts', '100 feet (30.5 m) plus 25 feet (7.6 m) per additional level of experience', 'One minute per level of experience', 'Area effect: Horror Factor 16, then a slick no one crosses without a save', '-3, but can be rolled at the start of every new melee round', 'Up to a 10 foot (3 m) radius per level of experience', 'Requires the sacrifice of a warm-blooded animal at least the size of a cat, plus a drop of the caster''s own blood', 'Thick, foul-smelling blood spatters walls and floor across the area. Everyone there first saves against a Horror Factor of 16, then against magic: on a failure they cannot get more than a yard across the gore before slipping back, and must go around or try again each melee round until they save. Works in rooms, corridors, stairwells or open ground. The enchanted blood is worthless to blood-drinkers and to devices such as Blood Bane power armor, and only magical rain shifts it early (1D6+3 minutes); when the spell lapses it runs off and cleans up like water. Anyone who falls in is coated, at -6 to M.A. and P.B. until they wash and change.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Spray', 2, 6, '6 P.P.E. plus a nick that inflicts 1D4 S.D.C. on the caster', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.93', 'rifts', '10 feet (3 m) plus 3 feet (.9 m) per level of the caster', 'Until washed away', NULL, 'Dodge 14 or higher', NULL, NULL, 'The caster opens a cut on his hand and aims it; about a gallon of blood jets out at the target. Failing the dodge blinds the victim for 1D4 melee rounds while he clears his eyes (half that with water to hand) and drenches his clothes or armor, marking him for others. Sealed armor, visors or goggles protect the eyes, but the wearer must spend a full melee round wiping or two actions removing the eyewear. It can also stage a scene of murder or torture to frighten people; that much blood has a Horror Factor of 13, and its scent may draw or confuse predators, above all in water.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Armor', 3, 7, '7 with a blood sacrifice, 21 without one', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.93-94', 'rifts', 'Self or another by touch, or 10 feet (3 m); the blood glob is hurled up to 12 feet (3.7 m)', 'Two minutes per level of the spell caster', 'None; 13 M.D.C. of protection per level of the spell caster', 'Standard if the magic is unwanted', NULL, 'Optional sacrifice of a warm-blooded animal the size of a cat or larger for the lower cost', 'Coats the recipient in real, dripping gore that acts as armor worth 13 M.D.C. per caster level and adds +2 to his Horror Factor (or gives him H.F. 11 if he had none). Lying still among corpses, he passes for dead just as with Death Trance. The slick coating puts anyone trying to grab, hold, pin or entangle him at -4. Once per melee round, as an extra attack, he may fling a gob at a foe''s eyes: a Called Shot at -5 that blinds the target (-10 to all combat rolls) until it is washed out or 1D4+2 melee rounds pass; helmets, eye protection and sealed armor only cost two actions to wipe clean. It works in vacuum, and Demon Knights rely on it.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Blade', 3, 6, '6 with a blood sacrifice, 12 with the caster''s own blood, 18 with the blood of another', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.94', 'rifts', 'Touch', 'Five minutes per level of the spell caster', 'Mega-Damage equal to the weapon''s normal S.D.C. damage', 'Not applicable', NULL, 'The whole blade is bloodied first: a sacrificed warm-blooded animal of rat size or more (lowest cost), the caster''s own blood (at least 1D6+1 Hit Points), or the blood of a foe or an innocent left alive', 'For warriors without a magic weapon. Once a bladed weapon (knife, sword, spear or pole arm only) is smeared with blood and enchanted, it inflicts its ordinary S.D.C. damage as M.D., so a 2D6 sword strikes for 2D6 M.D. The blade stays bloody for the duration and the blood drains away when it ends.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Source', 3, 8, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.94', 'rifts', 'Self only; the Soulmancer must be touching the blood', 'The extra P.P.E. must be spent within one hour', NULL, 'None', NULL, 'Needs fresh blood from a victim killed no more than four hours earlier', 'Turns spilled blood into P.P.E. for the Soulmancer: each pint gives him 10 points, and an adult human body holds about 8 pints (80 P.P.E.). The donor must already be dead and the blood under four hours old. As he casts with his hands in the blood, it boils off into steam.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Young Blood', 3, 13, '13 with a sacrifice, 23 without', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.94', 'rifts', 'Self or other via ritual and the drinking of blood', 'One hour per level of the Soulmancer; half for a creature of magic or supernatural being; doubled if the blood donor is slain', 'None; disguises the recipient', 'None if a willing participant, 16 if not (the block also prints Not applicable)', NULL, 'A short ritual: the recipient drinks at least 8 ounces of blood taken from a living mortal under 21 (animal blood will not do); killing the donor is the sacrifice', 'After the ritual the recipient looks younger, in steps of ten years, down to as little as half his real age, possibly a child. The change is complete and physical: physical attributes drop (by half as a teenager, by two-thirds as a child under 12), but skills, magic, psionics and mental attributes are untouched. Used for disguise and infiltration, as a punishment, or to bait someone into a dark deed with the false promise of lasting youth.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Mask', 4, 13, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.94', 'rifts', 'Self or other by touch', '10 minutes per level of the spell caster', 'None; disguises the recipient', 'Not applicable', NULL, 'The subject''s face and chest are smeared with any blood; killing a small animal supplies enough, but a sacrifice is not required', 'Changes the subject''s aura and body heat so that vampires, zombies, other undead and anything that senses or feeds on blood takes him for one of its own rather than food. They will not simply attack, though a stranger among them may still be questioned or quarrelled with.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Bloodthirsty', 4, 15, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.95', 'rifts', 'By touch or 20 feet (6.1 m); line of sight required; may be cast on oneself', 'Two melee rounds per level of the spell caster', NULL, '-2 to save if the target is angry, vengeful, wants to hurt or kill, or enjoys combat; +1 if the target is a pacifist', NULL, NULL, 'Stokes the urge to punish and kill. The affected person turns ruthless and merciless: +2 on initiative, +1 to strike and every blow lands at full damage. In exchange he is -4 on Perception Rolls, -2 to dodge and -10% on skills, and will not try to disarm, pin, entangle or take anyone alive. Kind or merciful characters can usually pull back before a killing blow, only with effort. He is hard to talk down while it lasts.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Boil & Brew Blood', 4, 5, '5 as part of a ritual/blood sacrifice (and double duration), 10 as a spell', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.95', 'rifts', 'Up to one gallon (3.8 liters) per level of experience, by touch or up to 10 feet (3 m) away; line of sight required', '15 minutes per level of the spell caster', NULL, 'Standard if the magic is unwanted', NULL, 'Spell, or a ritual with a blood sacrifice for the lower cost and double duration; the blood must be supplied', 'Brings liquid blood (in a pot or cauldron, or pooled on a surface; not dried) to a boil within one melee round and holds it at a simmer. It makes no blood itself. Boiling purifies it for soups, stews, drinks and potions, and many Soulmancers and their demon masters keep blood recipes tasty enough that a guest never guesses. It also serves to unnerve: blood seething on a table or floor with no heat source has a Horror Factor of 13.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Mist', 5, 8, '8 with a blood sacrifice, 36 without one', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.95', 'rifts', '150 feet (45.7 m) away per level of experience', 'Two melee rounds (30 seconds) per level of the spell caster', 'None; causes impaired vision', 'Standard', 'A 20 foot (6.1 m) radius per level of the spell caster', 'Optional sacrifice of a medium-sized or larger warm-blooded animal or person for the lower cost', 'A thin red fog fills the area and cuts sight to about a yard. Anyone inside who fails to save loses all sense of direction and cannot find the way out. Sensors, nightvision, thermal optics and other instruments are useless in it, so no one inside can be tracked by machine. Only fighting within 3 feet is possible; beyond that, attacks are made blind at -10. The caster cannot see through it either.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Secret', 5, 30, '30 P.P.E. plus 2D4 S.D.C. damage to the spell caster', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.95', 'rifts', 'Touch', 'Until the message is delivered or the courier is killed', NULL, 'None', NULL, NULL, 'Hides a message of up to 40 words in a courier''s blood. The caster composes it, casts while cutting himself for 2D4 S.D.C. (M.D. for a mega-damage being), and the courier drinks the fresh blood. To read it, the recipient cuts the courier for the same damage and drinks; the message plays in the caster''s voice. Whoever tastes the courier''s blood first gets it, so the defence is secrecy about who carries it, decoy couriers, and couriers who know only whom to report to, not the content.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Pseudo Life (Ritual)', 5, 0, 'No P.P.E.: one life essence (soul) as a spell; 10 lives sacrificed as a ritual', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.95-96', 'rifts', 'Touch or five feet (1.5 m) maximum', 'As an incantation, one body, skeleton or set of organs for five minutes per level of experience; as a ritual, one body per level of experience for six months per level, or permanently with the Permanency ritual', NULL, 'Standard', NULL, 'Incantation or ritual', 'A necromantic spell that sets bones, bodies or loose organs working: hearts beat, joints move, organs function. Necromancers use it to replace limbs and damaged organs, and it is a building block of larger works, including some Bone weapons, which it animates to chew bones for ammunition. Rarely useful alone in a fight. Whole bodies and limbs given Pseudo Life have the same stats and behave as under Animate and Command Dead.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Reveal Soul', 5, 10, '20, or 10 if the caster has a drop of the victim''s blood', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.96', 'rifts', '10 feet (3 m) or touch', 'Instant', NULL, 'Standard, or -1 to save if the caster has a drop of the victim''s blood', NULL, NULL, 'A darker cousin of Peer into the Soul. If the target fails to save, the caster learns his deepest fear, regret or shame, love, hatred or resentment, and desire: private secrets such as a dread of betrayal, an affair, a lost child, an addiction or a hunger for fame or power. These are tools for temptation, seduction, bribery and blackmail; telling the victim what is known shocks him as a Horror Factor of 15, which the G.M. may adjust. A successful save reveals nothing and makes the target immune to this spell for 1D4 days.', NULL, 'soulmancy', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 18 spells rows are in' AS assertion, count(*) AS got, 18 AS want
  FROM spells WHERE name IN ('Soulmancy: Blood Ink', 'Soulmancy: Death Trance', 'Soulmancy: Peer into the Soul', 'Soulmancy: Acid Blood Spit', 'Soulmancy: Blood Bath (Super-Healing)', 'Soulmancy: Blood Splatter', 'Soulmancy: Blood Spray', 'Soulmancy: Blood Armor', 'Soulmancy: Blood Blade', 'Soulmancy: Blood Source', 'Soulmancy: Young Blood', 'Soulmancy: Blood Mask', 'Soulmancy: Bloodthirsty', 'Soulmancy: Boil & Brew Blood', 'Soulmancy: Blood Mist', 'Soulmancy: Blood Secret', 'Soulmancy: Pseudo Life (Ritual)', 'Soulmancy: Reveal Soul') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~340-megaverse-in-flames-spells-a.sql');
